SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, [Рабочий(станции)].YEAR, [Рабочий(станции)].NUST, [Рабочий(станции)].E, [Рабочий(станции)].EOTP, [Рабочий(станции)].EURT, [Рабочий(станции)].EUST, [Рабочий(станции)].Q, [Рабочий(станции)].TURT, [Рабочий(станции)].TUST, [Рабочий(станции)].B, [Рабочий(станции)].GAZ, [Рабочий(станции)].MAZUT, [Рабочий(станции)].TORF, [Рабочий(станции)].SLAN, [Рабочий(станции)].PROCH, [Рабочий(станции)].UGOL, [Рабочий(станции)].DON, [Рабочий(станции)].PODM, [Рабочий(станции)].PECH, [Рабочий(доп_угли)].intin, [Рабочий(доп_угли)].vork, [Рабочий(станции)].ARKT, [Рабочий(станции)].KUZN, [Рабочий(станции)].URAL, [Рабочий(доп_угли)].sver, [Рабочий(доп_угли)].chel, [Рабочий(доп_угли)].kizel, [Рабочий(станции)].BASHK, [Рабочий(станции)].KAN, [Рабочий(доп_угли)].nazar, [Рабочий(доп_угли)].ibor, [Рабочий(доп_угли)].berez, [Рабочий(станции)].IRKUT, [Рабочий(доп_угли)].azey, [Рабочий(доп_угли)].cher, [Рабочий(станции)].HAK, [Рабочий(станции)].TUV, [Рабочий(станции)].BUR, [Рабочий(доп_угли)].gusin, [Рабочий(доп_угли)].tugn, [Рабочий(станции)].CHIT, [Рабочий(станции)].YAKUT, [Рабочий(станции)].AMUR, [Рабочий(станции)].URG, [Рабочий(станции)].PRIM, [Рабочий(станции)].MAG, [Рабочий(станции)].SAH, [Рабочий(станции)].QOTR, [Рабочий(станции)].SNK, [Рабочий(станции)].EWTP, [Рабочий(станции)].NT, [Рабочий(станции)].OBOR, [Рабочий(станции)].VED, [Рабочий(станции)].OBL, [Рабочий(станции)].DEP, [Рабочий(станции)].OES, [Рабочий(станции)].ER, [Рабочий(станции)].NUMB1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R
FROM ((([Рабочий(станции)] INNER JOIN Имена_станций ON [Рабочий(станции)].NUMB1120 = Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON [Рабочий(станции)].OES = Имена_ОЭС.oes) INNER JOIN Имена_областей ON [Рабочий(станции)].OBL = Имена_областей.OBL) LEFT JOIN [Рабочий(доп_угли)] ON ([Рабочий(станции)].NUMB1120 = [Рабочий(доп_угли)].NUMB1120) AND ([Рабочий(станции)].YEAR = [Рабочий(доп_угли)].YEAR)
WHERE ((([Рабочий(станции)].VED)>0));
